      }

      .product-art::after {
        width: 18%;
        height: 18%;
        transform: translate(44px, 38px);
        background: rgba(7, 9, 15, 0.55);
      }

      .tag {
        display: inline-flex;
        width: fit-content;
        border: 1px solid rgba(255, 255, 255, 0.12);
