      function Deals() {
        return el(`
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="section-header">
              <div>
                <p class="eyebrow">Current deals</p>
                <h2 id="deals-heading">Limited offers, no clutter.</h2>
                <p>Promotions designed for clear value: simple terms, premium categories, and no hidden coupon hunt.</p>
              </div>
            </div>
            <div class="deals-layout">
              ${DealCard(deals[0], true)}
              <div class="deal-stack">
                ${deals.slice(1).map((deal) => DealCard(deal)).join("")}
              </div>
            </div>
          </section>
        `);
      }

      function EditorialCard(story, index) {
        return el(`
          <li>
            <article class="editorial-card" aria-labelledby="story-${index}-heading">
              <div class="editorial-image" style="--accent: ${story.accent}" aria-hidden="true"></div>
              <div class="editorial-body">
                <p class="eyebrow">${story.category}</p>
                <h3 id="story-${index}-heading">${story.title}</h3>
                <p>${story.copy}</p>
