              <h2 id="newsletter-heading">Early access for members.</h2>
              <p>Receive private sale notices, editorial previews, and restock alerts for the pieces that sell out first.</p>
            </div>
            <form class="signup-form" novalidate>
              <label class="field-label" for="email">Email address</label>
              <p class="field-help" id="email-help">We will only send retail updates from North & Noir.</p>
              <div class="input-row">
                <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-help">
                <button class="button" type="submit">Join Noir Circle</button>
              </div>
            </form>
          </section>
        `);
      }

      function Footer() {
        return el(`
