<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>North & Noir Retail | Dark Luxury Ecommerce Home</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #07090f;
        --panel: #111620;
        --panel-strong: #171e2b;
        --text: #f7f3ea;
        --muted: #c7c0b4;
        --soft: #918a81;
        --gold: #f4c76d;
        --gold-strong: #ffd98c;
        --mint: #7df2c6;
        --rose: #ff8da1;
        --line: #2b3444;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
        --radius-xl: 32px;
        --radius-lg: 22px;
        --radius-md: 16px;
        --space: clamp(1rem, 3vw, 2rem);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(244, 199, 109, 0.18), transparent 34rem),
          radial-gradient(circle at 85% 12%, rgba(125, 242, 198, 0.12), transparent 28rem),
          linear-gradient(135deg, #07090f 0%, #0c1018 48%, #07090f 100%);
        color: var(--text);
        min-width: 320px;
      }

      body::before {
        content: "";
        position: fixed;
        inset: 0;
        pointer-events: none;
        background-image:
          linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
          linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
        background-size: 54px 54px;
        mask-image: linear-gradient(to bottom, #000, transparent 70%);
      }

      a {
        color: inherit;
      }

      img,
      svg {
        max-width: 100%;
      }

      button,
      input {
        font: inherit;
      }

      :focus-visible {
        outline: 3px solid var(--mint);
        outline-offset: 4px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 100;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--gold);
        color: #111;
        font-weight: 800;
        padding: 0.85rem 1.1rem;
        text-decoration: none;
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .sr-only {
        clip: rect(0 0 0 0);
        clip-path: inset(50%);
        height: 1px;
        overflow: hidden;
        position: absolute;
        white-space: nowrap;
        width: 1px;
      }

      .site-shell {
        position: relative;
        width: min(1180px, calc(100% - 2rem));
        margin: 0 auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 20;
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
        background: #07090f;
      }

      .header-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1rem 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        min-height: 44px;
        text-decoration: none;
        font-weight: 900;
        letter-spacing: 0.05em;
        text-transform: uppercase;
      }

      .brand-mark {
        display: grid;
        place-items: center;
        width: 42px;
        height: 42px;
        border: 1px solid rgba(244, 199, 109, 0.65);
        border-radius: 14px;
        background:
          linear-gradient(135deg, rgba(244, 199, 109, 0.26), rgba(255, 255, 255, 0.04)),
          #111620;
        color: var(--gold-strong);
      }

      .primary-nav ul,
      .footer-nav ul {
        display: flex;
        align-items: center;
        gap: 0.25rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .primary-nav a,
      .footer-nav a {
        display: inline-flex;
        align-items: center;
        min-height: 44px;
        border-radius: 999px;
        padding: 0.65rem 0.95rem;
        color: var(--muted);
        text-decoration: none;
      }

      .primary-nav a:hover,
      .footer-nav a:hover {
        color: var(--text);
        background: rgba(255, 255, 255, 0.08);
      }

      .header-actions {
        display: flex;
        align-items: center;
        gap: 0.65rem;
      }

      .cart-button,
      .button,
      .icon-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        cursor: pointer;
        text-decoration: none;
      }

      .cart-button,
      .icon-button {
        min-width: 44px;
        border: 1px solid var(--line);
        background: rgba(255, 255, 255, 0.06);
        color: var(--text);
      }

      .button {
        border: 1px solid transparent;
        padding: 0.85rem 1.2rem;
        background: var(--gold);
        color: #14100a;
        font-weight: 850;
      }

      .button:hover {
        background: var(--gold-strong);
      }

      .button.secondary {
        border-color: var(--line);
        background: rgba(255, 255, 255, 0.06);
        color: var(--text);
      }

      .button.secondary:hover,
      .cart-button:hover,
      .icon-button:hover {
        background: rgba(255, 255, 255, 0.12);
      }

      .count-badge {
        display: inline-grid;
        place-items: center;
        min-width: 1.65rem;
        height: 1.65rem;
        border-radius: 999px;
        background: var(--mint);
        color: #06110d;
        font-size: 0.85rem;
        font-weight: 900;
      }

      main {
        padding: clamp(2rem, 5vw, 4rem) 0 0;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.05fr) minmax(280px, 0.95fr);
        gap: clamp(1.5rem, 4vw, 3rem);
        align-items: stretch;
        min-height: 640px;
      }

      .hero-copy {
        display: flex;
        flex-direction: column;
        justify-content: center;
        padding: clamp(1.25rem, 4vw, 3rem);
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-xl);
        background: #111620;
        box-shadow: var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.5rem;
        margin: 0 0 1rem;
        border: 1px solid rgba(244, 199, 109, 0.38);
        border-radius: 999px;
        padding: 0.45rem 0.75rem;
        color: var(--gold-strong);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.11em;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        line-height: 1.02;
      }

      h1 {
        max-width: 12ch;
        font-size: clamp(3.1rem, 8vw, 7rem);
        letter-spacing: -0.075em;
      }

      h2 {
        font-size: clamp(2rem, 5vw, 4rem);
        letter-spacing: -0.055em;
      }

      h3 {
        font-size: 1.15rem;
        letter-spacing: -0.02em;
      }

      .hero-copy p {
        max-width: 62ch;
        margin: 1.25rem 0 0;
        color: var(--muted);
        font-size: clamp(1.05rem, 2vw, 1.25rem);
        line-height: 1.7;
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.8rem;
        margin-top: 2rem;
      }

      .hero-card {
        position: relative;
        display: grid;
        align-content: end;
        overflow: hidden;
        min-height: 520px;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-xl);
        background:
          radial-gradient(circle at 55% 24%, rgba(244, 199, 109, 0.32), transparent 18rem),
          radial-gradient(circle at 40% 46%, rgba(125, 242, 198, 0.17), transparent 15rem),
          linear-gradient(160deg, #1b2030 0%, #0b0e15 100%);
        box-shadow: var(--shadow);
      }

      .orbital-display {
        position: absolute;
        inset: 11% 8% auto;
        height: min(55vw, 390px);
        border-radius: 999px;
        background:
          radial-gradient(circle at 50% 46%, #f5d28b 0 8%, transparent 8.4%),
          radial-gradient(circle at 35% 38%, #f6f1e8 0 5%, transparent 5.4%),
          radial-gradient(circle at 68% 42%, #7df2c6 0 4.8%, transparent 5.2%),
          radial-gradient(circle at 55% 66%, #ff8da1 0 4.5%, transparent 4.9%),
          conic-gradient(from 20deg, transparent 0 14%, rgba(244, 199, 109, 0.55) 14% 16%, transparent 16% 45%, rgba(125, 242, 198, 0.4) 45% 47%, transparent 47% 100%);
        filter: drop-shadow(0 24px 60px rgba(244, 199, 109, 0.18));
      }

      .hero-card-content {
        position: relative;
        margin: 1rem;
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 26px;
        padding: 1.25rem;
        background: #07090f;
      }

      .hero-card-content p {
        margin: 0.6rem 0 0;
        color: var(--muted);
        line-height: 1.55;
      }

      .section {
        padding: clamp(3rem, 7vw, 6rem) 0 0;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.3rem;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-lg);
        padding: 1rem;
        background: #07090f;
      }

      .section-header p {
        max-width: 42rem;
        margin: 0.75rem 0 0;
        color: var(--muted);
        line-height: 1.65;
      }

      .view-link {
        display: inline-flex;
        align-items: center;
        min-height: 44px;
        border-radius: 999px;
        color: var(--gold-strong);
        font-weight: 800;
        text-decoration: none;
        white-space: nowrap;
      }

      .grid {
        display: grid;
        gap: 1rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .editorial-card {
        position: relative;
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.09);
        border-radius: var(--radius-lg);
        background: #111620;
      }

      .product-card {
        display: flex;
        flex-direction: column;
        min-height: 100%;
        padding: 0.9rem;
      }

      .product-art {
        position: relative;
        display: grid;
        place-items: center;
        min-height: 220px;
        border-radius: 18px;
        background:
          radial-gradient(circle at 50% 42%, var(--accent), transparent 0 22%, transparent 23%),
          radial-gradient(circle at 50% 52%, rgba(255, 255, 255, 0.18), transparent 0 33%, transparent 34%),
          linear-gradient(145deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.02));
      }

      .product-art::before,
      .product-art::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        background: color-mix(in srgb, var(--accent) 78%, white 22%);
      }

      .product-art::before {
        width: 42%;
        height: 42%;
        box-shadow:
