        margin: 0.75rem 0 0;
        color: var(--muted);
        line-height: 1.65;
      }

      .view-link {
        display: inline-flex;
        align-items: center;
        min-height: 44px;
        border-radius: 999px;
        color: var(--gold-strong);
        font-weight: 800;
        text-decoration: none;
        white-space: nowrap;
      }

      .grid {
        display: grid;
        gap: 1rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .editorial-card {
        position: relative;
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.09);
        border-radius: var(--radius-lg);
        background: #111620;
      }

      .product-card {
        display: flex;
        flex-direction: column;
        min-height: 100%;
        padding: 0.9rem;
      }

      .product-art {
        position: relative;
        display: grid;
        place-items: center;
        min-height: 220px;
        border-radius: 18px;
        background:
          radial-gradient(circle at 50% 42%, var(--accent), transparent 0 22%, transparent 23%),
          radial-gradient(circle at 50% 52%, rgba(255, 255, 255, 0.18), transparent 0 33%, transparent 34%),
          linear-gradient(145deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.02));
      }

      .product-art::before,
      .product-art::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        background: color-mix(in srgb, var(--accent) 78%, white 22%);
      }

      .product-art::before {
        width: 42%;
        height: 42%;
        box-shadow:
          -48px 34px 0 -20px rgba(255, 255, 255, 0.18),
          52px -28px 0 -24px rgba(255, 255, 255, 0.22);
      }

      .product-art::after {
        width: 18%;
        height: 18%;
        transform: translate(44px, 38px);
        background: rgba(7, 9, 15, 0.55);
      }

      .tag {
        display: inline-flex;
        width: fit-content;
        border: 1px solid rgba(255, 255, 255, 0.12);
        border-radius: 999px;
        padding: 0.35rem 0.55rem;
        color: var(--mint);
        font-size: 0.78rem;
        font-weight: 800;
      }

      .product-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        padding: 1rem 0.2rem 0.2rem;
      }

      .product-title-link {
        text-decoration: none;
      }

      .product-title-link:hover {
        color: var(--gold-strong);
      }

      .product-meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        margin: 0.75rem 0 1rem;
        color: var(--muted);
