      }

      @media (max-width: 620px) {
        .site-shell {
          width: min(100% - 1rem, 1180px);
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .section-header,
        .input-row {
          align-items: stretch;
          flex-direction: column;
        }

        .view-link {
          white-space: normal;
        }

        .hero-copy,
        .hero-card-content,
        .newsletter {
          border-radius: 22px;
        }
      }
    </style>
