          <section class="section" id="featured" aria-labelledby="featured-heading">
            <div class="section-header">
              <div>
                <p class="eyebrow">Featured products</p>
                <h2 id="featured-heading">Curated for the week.</h2>
                <p>Four retail essentials selected for premium materials, strong silhouettes, and gift-ready presentation.</p>
              </div>
              <a class="view-link" href="#featured">View all featured products</a>
            </div>
            <ul class="grid product-grid">
              ${products.map(ProductCard).join("")}
            </ul>
          </section>
        `);
      }

      function DealCard(deal, isFeatured = false) {
        return el(`
          <article class="deal-card ${isFeatured ? "featured" : ""}" aria-labelledby="${deal.title.toLowerCase().replaceAll(" ", "-")}-heading">
            <h3 id="${deal.title.toLowerCase().replaceAll(" ", "-")}-heading">${deal.title}</h3>
            <span class="deal-value">${deal.value}</span>
            <p>${deal.copy}</p>
            <a class="view-link" href="${deal.link}">Shop ${deal.title.toLowerCase()}</a>
          </article>
        `);
      }

      function Deals() {
        return el(`
          <section class="section" id="deals" aria-labelledby="deals-heading">
            <div class="section-header">
              <div>
                <p class="eyebrow">Current deals</p>
                <h2 id="deals-heading">Limited offers, no clutter.</h2>
                <p>Promotions designed for clear value: simple terms, premium categories, and no hidden coupon hunt.</p>
              </div>
            </div>
            <div class="deals-layout">
              ${DealCard(deals[0], true)}
              <div class="deal-stack">
                ${deals.slice(1).map((deal) => DealCard(deal)).join("")}
              </div>
            </div>
          </section>
        `);
      }

      function EditorialCard(story, index) {
        return el(`
          <li>
            <article class="editorial-card" aria-labelledby="story-${index}-heading">
              <div class="editorial-image" style="--accent: ${story.accent}" aria-hidden="true"></div>
              <div class="editorial-body">
                <p class="eyebrow">${story.category}</p>
                <h3 id="story-${index}-heading">${story.title}</h3>
                <p>${story.copy}</p>
                <a class="view-link" href="#editorial">Read: ${story.title}</a>
              </div>
            </article>
          </li>
        `);
      }

      function Editorial() {
        return el(`
          <section class="section" id="editorial" aria-labelledby="editorial-heading">
            <div class="section-header">
              <div>
                <p class="eyebrow">Editorial content</p>
                <h2 id="editorial-heading">Stories from the floor.</h2>
                <p>Buying notes, styling direction, and behind-the-scenes material choices from the North & Noir team.</p>
              </div>
              <a class="view-link" href="#editorial">Browse all stories</a>
            </div>
            <ul class="grid editorial-grid">
              ${stories.map(EditorialCard).join("")}
            </ul>
          </section>
        `);
      }

      function Newsletter() {
        return el(`
          <section class="newsletter" id="newsletter" aria-labelledby="newsletter-heading">
            <div>
              <p class="eyebrow">Noir Circle</p>
              <h2 id="newsletter-heading">Early access for members.</h2>
              <p>Receive private sale notices, editorial previews, and restock alerts for the pieces that sell out first.</p>
            </div>
            <form class="signup-form" novalidate>
              <label class="field-label" for="email">Email address</label>
              <p class="field-help" id="email-help">We will only send retail updates from North & Noir.</p>
              <div class="input-row">
                <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-help">
                <button class="button" type="submit">Join Noir Circle</button>
              </div>
            </form>
          </section>
        `);
      }

      function Footer() {
        return el(`
          <footer class="site-footer">
            <div class="site-shell footer-inner">
              <p>&copy; 2026 North & Noir Retail Studio</p>
              <nav class="footer-nav" aria-label="Footer">
                <ul>
                  <li><a href="#featured">Products</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Editorial</a></li>
                  <li><a href="#newsletter">Membership</a></li>
                </ul>
              </nav>
            </div>
          </footer>
        `);
      }

      function App() {
        return el(`
          ${Header()}
          <main id="maincontent" class="site-shell" tabindex="-1">
            ${Hero()}
            ${FeaturedProducts()}
            ${Deals()}
            ${Editorial()}
            ${Newsletter()}
          </main>
          ${Footer()}
        `);
      }

      function announce(message) {
        document.getElementById("announcements").textContent = message;
      }

      function updateCart(name) {
        cartCount += 1;
        document.querySelector("[data-cart-count]").textContent = cartCount;
        document.querySelector(".cart-button").setAttribute("aria-label", `Cart, ${cartCount} ${cartCount === 1 ? "item" : "items"}`);
        announce(`${name} added to cart. Cart now has ${cartCount} ${cartCount === 1 ? "item" : "items"}.`);
      }

      function bindInteractions() {
        document.querySelectorAll(".add-to-cart").forEach((button) => {
          button.addEventListener("click", () => updateCart(button.dataset.productName));
        });

        document.querySelector(".signup-form").addEventListener("submit", (event) => {
          event.preventDefault();
          const email = document.getElementById("email");

          if (!email.checkValidity()) {
            email.reportValidity();
            announce("Enter a valid email address to join Noir Circle.");
            return;
          }

          announce("Thanks for joining Noir Circle. Watch your inbox for early access.");
          event.currentTarget.reset();
        });
      }

      document.getElementById("app").innerHTML = App();
      bindInteractions();
    </script>
  </body>
</html>
