        document.querySelector(".cart-button").setAttribute("aria-label", `Cart, ${cartCount} ${cartCount === 1 ? "item" : "items"}`);
        announce(`${name} added to cart. Cart now has ${cartCount} ${cartCount === 1 ? "item" : "items"}.`);
      }

